/* T-matrix (EBCM) for axisymmetric particles: browser port of tmatrix.py.
 *
 * tmatrix.py is the ground truth (81 validation checks, including exact agreement
 * with Lorenz-Mie at eps = 1 and with the Rayleigh-ellipsoid limit). This file is a
 * deliberate line-by-line port, cross-checked in the browser by TM.selfTest against
 * reference values generated by crosscheck.py.
 *
 * Provenance: Waterman's EBCM as implemented by M. I. Mishchenko (ampld.lp.f).
 *
 * Complex matrices are stored as {re, im} pairs of Float64Array, row-major.
 * Nothing allocates inside the hot loops except the per-block matrices.
 */
const TM = (function () {
  'use strict';

  const SPHEROID = 'spheroid', CYLINDER = 'cylinder', CHEBYSHEV = 'chebyshev', BICONCAVE = 'biconcave';

  // Evans-Fung (1972) dimensionless red-blood-cell profile (see tmatrix.py).
  const EF = [0.1035805, 1.001279, -0.561381];
  function rbcZtop(u) {
    const s = Math.sqrt(Math.max(1 - u * u, 0));
    return s * (EF[0] + EF[1] * u * u + EF[2] * u ** 4);
  }
  // dimensionless volume for R0 = 1, by trapezoid (matches the Python constant)
  const RBC_VDIM = (() => {
    const N = 200001; let acc = 0, up = 0;
    for (let i = 0; i < N; i++) {
      const u = i / (N - 1), f = 4 * Math.PI * u * rbcZtop(u);
      if (i > 0) acc += 0.5 * (f + up) / (N - 1);
      up = f;
    }
    return acc;
  })();

  /* ---------------- quadrature ---------------- */

  function gaussLegendre(n) {
    const x = new Float64Array(n), w = new Float64Array(n);
    const m = (n + 1) >> 1;
    for (let i = 0; i < m; i++) {
      let z = Math.cos(Math.PI * (i + 0.75) / (n + 0.5));
      let pp = 0;
      for (let it = 0; it < 100; it++) {
        let p1 = 1.0, p2 = 0.0;
        for (let j = 0; j < n; j++) { const p3 = p2; p2 = p1; p1 = ((2 * j + 1) * z * p2 - j * p3) / (j + 1); }
        pp = n * (z * p1 - p2) / (z * z - 1.0);
        const dz = p1 / pp;
        z -= dz;
        if (Math.abs(dz) < 1e-15) break;
      }
      x[i] = -z; x[n - 1 - i] = z;
      w[i] = 2.0 / ((1.0 - z * z) * pp * pp); w[n - 1 - i] = w[i];
    }
    return { x, w };
  }

  function gaussNodes(ngauss, shape, eps) {
    const ng = 2 * ngauss;
    if (shape !== CYLINDER) return gaussLegendre(ng);

    const ng1 = Math.floor(ngauss / 2), ng2 = ngauss - ng1;
    const xx = -Math.cos(Math.atan(eps));
    const x = new Float64Array(ng), w = new Float64Array(ng);
    const a = gaussLegendre(ng1), b = gaussLegendre(ng2);
    for (let i = 0; i < ng1; i++) {
      x[i] = 0.5 * (xx + 1) * a.x[i] + 0.5 * (xx - 1);
      w[i] = 0.5 * (xx + 1) * a.w[i];
    }
    for (let i = 0; i < ng2; i++) {
      x[ng1 + i] = -0.5 * xx * b.x[i] + 0.5 * xx;
      w[ng1 + i] = -0.5 * xx * b.w[i];
    }
    for (let i = 0; i < ngauss; i++) { x[ng - 1 - i] = -x[i]; w[ng - 1 - i] = w[i]; }
    return { x, w };
  }

  function profile(x, rev, shape, eps, chebN) {
    const ng = x.length;
    const r2 = new Float64Array(ng), drr = new Float64Array(ng);
    if (shape === SPHEROID) {
      const a = rev * Math.cbrt(eps), ee = eps * eps;
      for (let i = 0; i < ng; i++) {
        const cc = x[i] * x[i], ss = 1 - cc;
        const rr = 1.0 / (ss + ee * cc);
        r2[i] = a * a * rr;
        drr[i] = rr * x[i] * Math.sqrt(ss) * (ee - 1.0);
      }
      return { r2, drr };
    }
    if (shape === CYLINDER) {
      const h = rev * Math.cbrt(2.0 / (3.0 * eps * eps)), a = h * eps;
      const n = ng >> 1;
      for (let i = 0; i < n; i++) {
        const co = -x[i], si = Math.sqrt(1 - co * co);
        const onCap = (si / co) <= (a / h);
        const rad = onCap ? h / co : a / si;
        const rthet = onCap ? h * si / (co * co) : -a * co / (si * si);
        r2[i] = rad * rad;
        drr[i] = -rthet / rad;
        r2[ng - 1 - i] = r2[i];
        drr[ng - 1 - i] = -drr[i];
      }
      return { r2, drr };
    }
    if (shape === BICONCAVE) {
      const R0 = rev * Math.cbrt((4 / 3 * Math.PI) / RBC_VDIM);
      const ztop = rho => R0 * rbcZtop(rho / R0);
      const ztopP = rho => {                                  // d z_top / d rho
        const u = rho / R0, s = Math.sqrt(Math.max(1 - u * u, 1e-300));
        const P = EF[0] + EF[1] * u * u + EF[2] * u ** 4;
        return -u / s * P + 2 * u * s * (EF[1] + 2 * EF[2] * u * u);
      };
      for (let i = 0; i < ng; i++) {
        const t = Math.abs(x[i]) / Math.sqrt(1 - x[i] * x[i]);
        let lo = 1e-12 * R0, hi = R0;
        for (let it = 0; it < 60; it++) {
          const mid = 0.5 * (lo + hi);
          if (ztop(mid) - t * mid > 0) lo = mid; else hi = mid;
        }
        const rho = 0.5 * (lo + hi), z = ztop(rho), zp = ztopP(rho);
        r2[i] = rho * rho + z * z;
        drr[i] = Math.sign(x[i]) * (rho + z * zp) / (z - rho * zp);
      }
      return { r2, drr };
    }

    // Chebyshev
    const dnp = chebN, dn = dnp * dnp, ep = eps * eps;
    let a = 1.0 + 1.5 * ep * (4 * dn - 2) / (4 * dn - 1);
    if (chebN % 2 === 0) a -= 3.0 * eps * (1 + 0.25 * ep) / (dn - 1) + 0.25 * ep * eps / (9 * dn - 1);
    const r0 = rev * Math.pow(a, -1.0 / 3.0);
    for (let i = 0; i < ng; i++) {
      const xi = Math.acos(x[i]) * dnp;
      const ri = r0 * (1 + eps * Math.cos(xi));
      r2[i] = ri * ri;
      drr[i] = -r0 * eps * dnp * Math.sin(xi) / ri;
    }
    return { r2, drr };
  }

  /* ---------------- Wigner d functions ---------------- */

  /* dv1[i*(nmax+1)+n] = d^n_{0m}(theta_i), dv2 = d/dtheta of it */
  function vig(x, nmax, m) {
    const ng = x.length, S = nmax + 1;
    const dv1 = new Float64Array(ng * S), dv2 = new Float64Array(ng * S);
    for (let i = 0; i < ng; i++) {
      const xi = x[i], qs = Math.sqrt(1 - xi * xi), qs1 = 1 / qs;
      if (m === 0) {
        let d1 = 1.0, d2 = xi;
        for (let n = 1; n <= nmax; n++) {
          const qn = n, qn1 = n + 1, qn2 = 2 * n + 1;
          const d3 = (qn2 * xi * d2 - qn * d1) / qn1;
          dv1[i * S + n] = d2;
          dv2[i * S + n] = qs1 * (qn1 * qn / qn2) * (-d1 + d3);
          d1 = d2; d2 = d3;
        }
      } else {
        const qmm = m * m;
        let a = 1.0;
        for (let j = 1; j <= m; j++) a *= Math.sqrt((2 * j - 1) / (2 * j)) * qs;
        let d1 = 0.0, d2 = a;
        for (let n = m; n <= nmax; n++) {
          const qn = n, qn1 = n + 1, qn2 = 2 * n + 1;
          const qnm = Math.sqrt(qn * qn - qmm), qnm1 = Math.sqrt(qn1 * qn1 - qmm);
          const d3 = (qn2 * xi * d2 - qnm * d1) / qnm1;
          dv1[i * S + n] = d2;
          dv2[i * S + n] = qs1 * (-qn1 * qnm * d1 + qn * qnm1 * d3) / qn2;
          d1 = d2; d2 = d3;
        }
      }
    }
    return { dv1, dv2 };
  }

  /* d^n_{0m}/sin(theta) and derivative; handles the poles.
     Writes into caller-supplied buffers: this is the hot loop of amplitudesVec, and
     allocating (ndir x nmax) per m inside a beta loop dominated the runtime. */
  function vigamplInto(x, nmax, m, dv1, dv2) {
    const ng = x.length, S = nmax + 1;
    dv1.fill(0, 0, ng * S); dv2.fill(0, 0, ng * S);
    for (let i = 0; i < ng; i++) {
      const xi = x[i];
      if (Math.abs(1 - Math.abs(xi)) <= 1e-10) {
        if (m !== 1) continue;
        for (let n = 1; n <= nmax; n++) {
          let dn = 0.5 * Math.sqrt(n * (n + 1));
          if (xi < 0) dn *= (n % 2 === 0) ? -1 : 1;      // (-1)^(n+1)
          dv1[i * S + n] = dn;
          dv2[i * S + n] = (xi < 0) ? -dn : dn;
        }
        continue;
      }
      // inline the recurrence: this sits in the hot loop of amplitudesVec, and a
      // per-node allocation here dominated the profile
      const qs = Math.sqrt(1 - xi * xi), qs1 = 1 / qs;
      if (m === 0) {
        let d1 = 1.0, d2 = xi;
        for (let n = 1; n <= nmax; n++) {
          const qn = n, qn1 = n + 1, qn2 = 2 * n + 1;
          const d3 = (qn2 * xi * d2 - qn * d1) / qn1;
          dv1[i * S + n] = d2 * qs1;
          dv2[i * S + n] = qs1 * (qn1 * qn / qn2) * (-d1 + d3);
          d1 = d2; d2 = d3;
        }
      } else {
        const qmm = m * m;
        let a = 1.0;
        for (let j = 1; j <= m; j++) a *= Math.sqrt((2 * j - 1) / (2 * j)) * qs;
        let d1 = 0.0, d2 = a;
        for (let n = m; n <= nmax; n++) {
          const qn = n, qn1 = n + 1, qn2 = 2 * n + 1;
          const qnm = Math.sqrt(qn * qn - qmm), qnm1 = Math.sqrt(qn1 * qn1 - qmm);
          const d3 = (qn2 * xi * d2 - qnm * d1) / qnm1;
          dv1[i * S + n] = d2 * qs1;
          dv2[i * S + n] = qs1 * (-qn1 * qnm * d1 + qn * qnm1 * d3) / qn2;
          d1 = d2; d2 = d3;
        }
      }
    }
  }

  function vigampl(x, nmax, m) {
    const S = nmax + 1;
    const dv1 = new Float64Array(x.length * S), dv2 = new Float64Array(x.length * S);
    vigamplInto(x, nmax, m, dv1, dv2);
    return { dv1, dv2 };
  }

  /* ---------------- Bessel tables ---------------- */

  function besselTables(kr, mr, mi, nmax) {
    const ng = kr.length, S = nmax + 1;
    const jr = new Float64Array(ng * S), y = new Float64Array(ng * S);
    const jcR = new Float64Array(ng * S), jcI = new Float64Array(ng * S);
    const dj = new Float64Array(ng * S), dy = new Float64Array(ng * S);
    const djcR = new Float64Array(ng * S), djcI = new Float64Array(ng * S);

    const absw = Math.hypot(mr, mi) * Math.max(...kr);
    const ns = nmax + Math.floor(absw) + 30;
    const t1 = new Float64Array(ns + 2), t2 = new Float64Array(ns + 2);
    const bR = new Float64Array(S), bI = new Float64Array(S);

    for (let i = 0; i < ng; i++) {
      const x = kr[i];
      MIE.sphJnComplex(nmax, x, 0.0, bR, bI, t1, t2);
      for (let n = 0; n <= nmax; n++) jr[i * S + n] = bR[n];

      y[i * S + 0] = -Math.cos(x) / x;
      y[i * S + 1] = -Math.cos(x) / (x * x) - Math.sin(x) / x;
      for (let n = 1; n < nmax; n++) y[i * S + n + 1] = (2 * n + 1) / x * y[i * S + n] - y[i * S + n - 1];

      const wr = mr * x, wi = mi * x;
      MIE.sphJnComplex(nmax, wr, wi, bR, bI, t1, t2);
      for (let n = 0; n <= nmax; n++) { jcR[i * S + n] = bR[n]; jcI[i * S + n] = bI[n]; }

      const wd = wr * wr + wi * wi;
      for (let n = 1; n <= nmax; n++) {
        dj[i * S + n] = jr[i * S + n - 1] - n * jr[i * S + n] / x;
        dy[i * S + n] = y[i * S + n - 1] - n * y[i * S + n] / x;
        const nr = n * wr / wd, ni = -n * wi / wd;
        const cr = jcR[i * S + n], ci = jcI[i * S + n];
        djcR[i * S + n] = jcR[i * S + n - 1] - (nr * cr - ni * ci);
        djcI[i * S + n] = jcI[i * S + n - 1] - (nr * ci + ni * cr);
      }
    }
    return { jr, y, jcR, jcI, dj, dy, djcR, djcI };
  }

  /* ---------------- complex linear algebra ---------------- */

  /* solve A X = B in place; A is N x N, B is N x M (row-major complex) */
  function zsolve(Ar, Ai, N, Br, Bi, M) {
    for (let c = 0; c < N; c++) {
      let piv = c, best = -1;
      for (let r = c; r < N; r++) {
        const v = Math.abs(Ar[r * N + c]) + Math.abs(Ai[r * N + c]);
        if (v > best) { best = v; piv = r; }
      }
      if (best === 0) throw new Error('singular Q');
      if (piv !== c) {
        for (let j = 0; j < N; j++) {
          let t = Ar[c * N + j]; Ar[c * N + j] = Ar[piv * N + j]; Ar[piv * N + j] = t;
          t = Ai[c * N + j]; Ai[c * N + j] = Ai[piv * N + j]; Ai[piv * N + j] = t;
        }
        for (let j = 0; j < M; j++) {
          let t = Br[c * M + j]; Br[c * M + j] = Br[piv * M + j]; Br[piv * M + j] = t;
          t = Bi[c * M + j]; Bi[c * M + j] = Bi[piv * M + j]; Bi[piv * M + j] = t;
        }
      }
      const ar = Ar[c * N + c], ai = Ai[c * N + c], d = ar * ar + ai * ai;
      for (let r = c + 1; r < N; r++) {
        const br = Ar[r * N + c], bi = Ai[r * N + c];
        const fr = (br * ar + bi * ai) / d, fi = (bi * ar - br * ai) / d;
        if (fr === 0 && fi === 0) continue;
        for (let j = c; j < N; j++) {
          const xr = Ar[c * N + j], xi = Ai[c * N + j];
          Ar[r * N + j] -= fr * xr - fi * xi;
          Ai[r * N + j] -= fr * xi + fi * xr;
        }
        for (let j = 0; j < M; j++) {
          const xr = Br[c * M + j], xi = Bi[c * M + j];
          Br[r * M + j] -= fr * xr - fi * xi;
          Bi[r * M + j] -= fr * xi + fi * xr;
        }
      }
    }
    for (let c = N - 1; c >= 0; c--) {
      const ar = Ar[c * N + c], ai = Ai[c * N + c], d = ar * ar + ai * ai;
      for (let j = 0; j < M; j++) {
        let sr = Br[c * M + j], si = Bi[c * M + j];
        for (let kk = c + 1; kk < N; kk++) {
          const xr = Ar[c * N + kk], xi = Ai[c * N + kk];
          const yr = Br[kk * M + j], yi = Bi[kk * M + j];
          sr -= xr * yr - xi * yi;
          si -= xr * yi + xi * yr;
        }
        Br[c * M + j] = (sr * ar + si * ai) / d;
        Bi[c * M + j] = (si * ar - sr * ai) / d;
      }
    }
  }

  /* ---------------- the T-matrix block ---------------- */

  function tmatrixBlock(m, k, mr, mi, x, w, r2, drr, B, nmax) {
    const nmin = Math.max(m, 1), nm = nmax - nmin + 1, ng = x.length, S = nmax + 1;
    const md = mr * mr + mi * mi;

    const sinth = new Float64Array(ng), rr = new Float64Array(ng);
    const ds = new Float64Array(ng), dss = new Float64Array(ng);
    const ddr = new Float64Array(ng), imkR = new Float64Array(ng), imkI = new Float64Array(ng);
    for (let i = 0; i < ng; i++) {
      sinth[i] = Math.sqrt(1 - x[i] * x[i]);
      const r = Math.sqrt(r2[i]);
      rr[i] = w[i] * r2[i];
      ds[i] = rr[i] * m / sinth[i];
      dss[i] = (m * m) / (sinth[i] * sinth[i]);
      ddr[i] = 1.0 / (k * r);
      const wr = mr * k * r, wi = mi * k * r, wd = wr * wr + wi * wi;
      imkR[i] = wr / wd; imkI[i] = -wi / wd;
    }

    const V = vig(x, nmax, m);

    // (ng x nm) complex slices
    const alloc = () => ({ re: new Float64Array(ng * nm), im: new Float64Array(ng * nm) });
    const d1 = new Float64Array(ng * nm), d2 = new Float64Array(ng * nm);
    const hR = new Float64Array(ng * nm), hI = new Float64Array(ng * nm);
    const dhR = new Float64Array(ng * nm), dhI = new Float64Array(ng * nm);
    const jR = new Float64Array(ng * nm), djR = new Float64Array(ng * nm);
    const jcR = new Float64Array(ng * nm), jcI = new Float64Array(ng * nm);
    const djcR = new Float64Array(ng * nm), djcI = new Float64Array(ng * nm);
    for (let i = 0; i < ng; i++) for (let q = 0; q < nm; q++) {
      const n = nmin + q, a = i * S + n, b = i * nm + q;
      d1[b] = V.dv1[a]; d2[b] = V.dv2[a];
      jR[b] = B.jr[a]; djR[b] = B.dj[a];
      hR[b] = B.jr[a]; hI[b] = B.y[a];
      dhR[b] = B.dj[a]; dhI[b] = B.dy[a];
      jcR[b] = B.jcR[a]; jcI[b] = B.jcI[a];
      djcR[b] = B.djcR[a]; djcI[b] = B.djcI[a];
    }

    const an = new Float64Array(nm);
    for (let q = 0; q < nm; q++) { const n = nmin + q; an[q] = n * (n + 1); }

    /* acc: out[n1*nm+n2] += sum_i wgt_i f1[i,n1] f2[i,n2] (complex f1,f2) */
    function acc(out, wgt, f1r, f1i, f2r, f2i, scale) {
      for (let i = 0; i < ng; i++) {
        const wi_ = wgt[i];
        if (wi_ === 0) continue;
        for (let p = 0; p < nm; p++) {
          const ar = f1r[i * nm + p] * wi_, ai = f1i ? f1i[i * nm + p] * wi_ : 0;
          if (ar === 0 && ai === 0) continue;
          for (let q = 0; q < nm; q++) {
            const br = f2r[i * nm + q], bi = f2i ? f2i[i * nm + q] : 0;
            const s = scale ? scale[p * nm + q] : 1;
            out.re[p * nm + q] += s * (ar * br - ai * bi);
            out.im[p * nm + q] += s * (ar * bi + ai * br);
          }
        }
      }
    }

    // temp (ng x nm) products used repeatedly
    const tmp = () => ({ re: new Float64Array(ng * nm), im: new Float64Array(ng * nm) });
    function mulRC(outR, outI, a, br, bi) {      // real x complex
      for (let t = 0; t < ng * nm; t++) { outR[t] = a[t] * br[t]; outI[t] = a[t] * (bi ? bi[t] : 0); }
    }
    function mulCC(outR, outI, ar, ai, br, bi) {
      for (let t = 0; t < ng * nm; t++) {
        outR[t] = ar[t] * br[t] - ai[t] * bi[t];
        outI[t] = ar[t] * bi[t] + ai[t] * br[t];
      }
    }

    const scratch = [];
    for (let s = 0; s < 8; s++) scratch.push(tmp());

    // per-node complex jc2 * invmkr
    const jcS = tmp();
    for (let i = 0; i < ng; i++) for (let q = 0; q < nm; q++) {
      const b = i * nm + q;
      jcS.re[b] = jcR[b] * imkR[i] - jcI[b] * imkI[i];
      jcS.im[b] = jcR[b] * imkI[i] + jcI[b] * imkR[i];
    }

    const zeros = () => ({ re: new Float64Array(nm * nm), im: new Float64Array(nm * nm) });
    const anRow = new Float64Array(nm * nm), anCol = new Float64Array(nm * nm);
    for (let p = 0; p < nm; p++) for (let q = 0; q < nm; q++) { anRow[p * nm + q] = an[p]; anCol[p * nm + q] = an[q]; }

    const wr1 = new Float64Array(ng), wr2 = new Float64Array(ng), wr3 = new Float64Array(ng);
    const wr4 = new Float64Array(ng), wr5 = new Float64Array(ng), wr6 = new Float64Array(ng);
    for (let i = 0; i < ng; i++) {
      wr1[i] = rr[i] * dss[i];
      wr2[i] = rr[i] * drr[i] * ddr[i];
      wr3[i] = rr[i] * drr[i];
      wr4[i] = ds[i] * drr[i] * ddr[i];
      wr5[i] = ds[i] * drr[i];
      wr6[i] = ds[i];
    }

    function surfaceIntegrals(hhR, hhI, dhhR, dhhI) {
      const a11 = zeros(), a12 = zeros(), a21 = zeros(), a22 = zeros();
      const P = scratch;
      mulRC(P[0].re, P[0].im, d1, hhR, hhI);      // d1 * hh
      mulRC(P[1].re, P[1].im, d2, hhR, hhI);      // d2 * hh
      mulRC(P[2].re, P[2].im, d1, dhhR, dhhI);    // d1 * dhh
      mulRC(P[3].re, P[3].im, d2, dhhR, dhhI);    // d2 * dhh
      mulRC(P[4].re, P[4].im, d1, jcR, jcI);      // d1 * jc2
      mulRC(P[5].re, P[5].im, d2, jcR, jcI);      // d2 * jc2
      mulRC(P[6].re, P[6].im, d1, djcR, djcI);    // d1 * djc2
      mulRC(P[7].re, P[7].im, d2, djcR, djcI);    // d2 * djc2
      const d1jcS = tmp(); mulRC(d1jcS.re, d1jcS.im, d1, jcS.re, jcS.im);

      acc(a11, wr6, P[0].re, P[0].im, P[5].re, P[5].im, null);
      acc(a11, wr6, P[1].re, P[1].im, P[4].re, P[4].im, null);

      acc(a12, wr1, P[2].re, P[2].im, P[4].re, P[4].im, null);
      acc(a12, rr, P[3].re, P[3].im, P[5].re, P[5].im, null);
      acc(a12, wr2, P[0].re, P[0].im, P[5].re, P[5].im, anRow);

      acc(a21, wr1, P[0].re, P[0].im, P[6].re, P[6].im, null);
      acc(a21, rr, P[1].re, P[1].im, P[7].re, P[7].im, null);
      acc(a21, wr3, P[1].re, P[1].im, d1jcS.re, d1jcS.im, anCol);

      acc(a22, wr6, P[2].re, P[2].im, P[7].re, P[7].im, null);
      acc(a22, wr6, P[3].re, P[3].im, P[6].re, P[6].im, null);
      acc(a22, wr4, P[0].re, P[0].im, P[6].re, P[6].im, anRow);
      acc(a22, wr5, P[2].re, P[2].im, d1jcS.re, d1jcS.im, anCol);

      return [a11, a12, a21, a22];
    }

    const Qa = surfaceIntegrals(hR, hI, dhR, dhI);
    const Ra = surfaceIntegrals(jR, null, djR, null);

    const dd = new Float64Array(nm);
    for (let q = 0; q < nm; q++) { const n = nmin + q; dd[q] = Math.sqrt((2 * n + 1) / (n * (n + 1))); }

    function assemble(A) {
      const [a11, a12, a21, a22] = A;
      const N = 2 * nm;
      const Mr = new Float64Array(N * N), Mi = new Float64Array(N * N);
      const tpiR = k * k * mr, tpiI = k * k * mi, tppi = k * k;
      for (let p = 0; p < nm; p++) for (let q = 0; q < nm; q++) {
        const s = 0.5 * dd[p] * dd[q], e = p * nm + q;
        const A11r = -a11.re[e] * s, A11i = -a11.im[e] * s;
        const A22r = -a22.re[e] * s, A22i = -a22.im[e] * s;
        const A12r = a12.im[e] * s, A12i = -a12.re[e] * s;    // -i * a12
        const A21r = -a21.im[e] * s, A21i = a21.re[e] * s;    //  i * a21
        const put = (R, C, xr, xi, yr, yi) => {
          Mr[R * N + C] = tpiR * xr - tpiI * xi + tppi * yr;
          Mi[R * N + C] = tpiR * xi + tpiI * xr + tppi * yi;
        };
        put(p, q, A21r, A21i, A12r, A12i);
        put(p, q + nm, A11r, A11i, A22r, A22i);
        put(p + nm, q, A22r, A22i, A11r, A11i);
        put(p + nm, q + nm, A12r, A12i, A21r, A21i);
      }
      return { re: Mr, im: Mi, N };
    }

    const Q = assemble(Qa), Rg = assemble(Ra);
    const N = 2 * nm;
    // T = -RgQ Q^{-1}  <=>  Q^T T^T = -RgQ^T
    const Ar = new Float64Array(N * N), Ai = new Float64Array(N * N);
    const Br = new Float64Array(N * N), Bi = new Float64Array(N * N);
    for (let p = 0; p < N; p++) for (let q = 0; q < N; q++) {
      Ar[p * N + q] = Q.re[q * N + p]; Ai[p * N + q] = Q.im[q * N + p];
      Br[p * N + q] = Rg.re[q * N + p]; Bi[p * N + q] = Rg.im[q * N + p];
    }
    zsolve(Ar, Ai, N, Br, Bi, N);
    const Tr = new Float64Array(N * N), Ti = new Float64Array(N * N);
    for (let p = 0; p < N; p++) for (let q = 0; q < N; q++) {
      Tr[p * N + q] = -Br[q * N + p]; Ti[p * N + q] = -Bi[q * N + p];
    }
    for (let t = 0; t < N * N; t++) if (!isFinite(Tr[t]) || !isFinite(Ti[t])) throw new Error('non-finite T');
    return { re: Tr, im: Ti, N, nm, nmin };
  }

  function nmaxDefault(xev) { return Math.max(4, Math.floor(xev + 4.05 * Math.cbrt(xev))); }

  function tmatrix(rev, k, mr, mi, shape, eps, nmax, ngauss, chebN) {
    const xev = k * rev;
    nmax = nmax || nmaxDefault(xev);
    ngauss = ngauss || nmax * 2;
    chebN = chebN || 2;
    const { x, w } = gaussNodes(ngauss, shape, eps);
    const { r2, drr } = profile(x, rev, shape, eps, chebN);
    const kr = new Float64Array(x.length);
    for (let i = 0; i < x.length; i++) kr[i] = k * Math.sqrt(r2[i]);
    const B = besselTables(kr, mr, mi, nmax);
    const blocks = [];
    for (let m = 0; m <= nmax; m++) blocks.push(tmatrixBlock(m, k, mr, mi, x, w, r2, drr, B, nmax));
    return { blocks, nmax };
  }

  function crossSectionsRandom(blocks, k, rev) {
    let qext = 0, qsca = 0;
    for (let m = 0; m < blocks.length; m++) {
      const T = blocks[m], fac = (m === 0) ? 1 : 2, N = T.N;
      for (let i = 0; i < N; i++) qext += fac * T.re[i * N + i];
      let s = 0;
      for (let t = 0; t < N * N; t++) s += T.re[t] * T.re[t] + T.im[t] * T.im[t];
      qsca += fac * s;
    }
    const cext = -(2 * Math.PI / (k * k)) * qext;
    const csca = (2 * Math.PI / (k * k)) * qsca;
    const geo = Math.PI * rev * rev;
    return { cext, csca, cabs: cext - csca, qext: cext / geo, qsca: csca / geo,
             qabs: (cext - csca) / geo, albedo: cext ? csca / cext : 0 };
  }

  /* ---------------- amplitude matrix ---------------- */

  function fullT(blocks, nmax) {
    const S = nmax + 1, sz = S * S;
    const T = [];
    for (let kk = 0; kk < 4; kk++) T.push({ re: new Float64Array((nmax + 1) * sz), im: new Float64Array((nmax + 1) * sz) });
    for (let m = 0; m <= nmax; m++) {
      const Bk = blocks[m], nm = Bk.nm, nmin = Bk.nmin, N = Bk.N;
      for (let p = 0; p < nm; p++) for (let q = 0; q < nm; q++) {
        const n = nmin + p, np = nmin + q, o = m * sz + n * S + np;
        T[0].re[o] = Bk.re[p * N + q];                 T[0].im[o] = Bk.im[p * N + q];
        T[1].re[o] = Bk.re[p * N + (q + nm)];          T[1].im[o] = Bk.im[p * N + (q + nm)];
        T[2].re[o] = Bk.re[(p + nm) * N + q];          T[2].im[o] = Bk.im[(p + nm) * N + q];
        T[3].re[o] = Bk.re[(p + nm) * N + (q + nm)];   T[3].im[o] = Bk.im[(p + nm) * N + (q + nm)];
      }
    }
    return T;
  }

  function calMatrix(nmax) {
    const S = nmax + 1;
    const rn = new Float64Array(S);
    for (let n = 1; n <= nmax; n++) rn[n] = Math.sqrt((2 * n + 1) / (n * (n + 1)));
    const re = new Float64Array(S * S), im = new Float64Array(S * S);
    const ir = [1, 0, -1, 0], ii = [0, 1, 0, -1];
    for (let n = 0; n <= nmax; n++) for (let np = 0; np <= nmax; np++) {
      const p = ((np - n - 1) % 4 + 4) % 4, c = rn[n] * rn[np];
      re[n * S + np] = ir[p] * c; im[n * S + np] = ii[p] * c;
    }
    return { re, im };
  }

  /* S for one incidence direction and many scattering directions.
     Meridional (theta_hat, phi_hat) basis, NOT the scattering plane. */
  function amplitudesVec(Tfull, nmax, k, ct0, ct, dphi) {
    const S = nmax + 1, nd = ct.length;
    const cal = calMatrix(nmax);
    const vvR = new Float64Array(nd), vvI = new Float64Array(nd);
    const vhR = new Float64Array(nd), vhI = new Float64Array(nd);
    const hvR = new Float64Array(nd), hvI = new Float64Array(nd);
    const hhR = new Float64Array(nd), hhI = new Float64Array(nd);
    const ct0a = new Float64Array([ct0]);

    // hoisted: reused across the m loop instead of reallocated (ndir x S) each time
    const DV1 = new Float64Array(nd * S), DV2 = new Float64Array(nd * S);
    const dv01 = new Float64Array(S), dv02 = new Float64Array(S);
    const DV = { dv1: DV1, dv2: DV2 }, dv0 = { dv1: dv01, dv2: dv02 };

    for (let m = 0; m <= nmax; m++) {
      vigamplInto(ct, nmax, m, DV1, DV2);
      vigamplInto(ct0a, nmax, m, dv01, dv02);
      const off = m * S * S;

      // M_ij = cal .* T_ij, contracted with the incidence vectors a, b
      const qa1R = new Float64Array(S), qa1I = new Float64Array(S);
      const qa2R = new Float64Array(S), qa2I = new Float64Array(S);
      const qb1R = new Float64Array(S), qb1I = new Float64Array(S);
      const qb2R = new Float64Array(S), qb2I = new Float64Array(S);

      const a = new Float64Array(S), b = new Float64Array(S);
      for (let n = 0; n <= nmax; n++) { a[n] = m * dv0.dv1[n]; b[n] = dv0.dv2[n]; }

      for (let n = 0; n <= nmax; n++) {
        for (let np = 0; np <= nmax; np++) {
          const cr = cal.re[n * S + np], ci = cal.im[n * S + np];
          const o = off + n * S + np;
          const g = (Tk, coef) => {
            const tr = Tk.re[o], ti = Tk.im[o];
            const mr_ = cr * tr - ci * ti, mi_ = cr * ti + ci * tr;
            return [mr_ * coef, mi_ * coef];
          };
          if (m === 0) {
            const [r22, i22] = g(Tfull[3], b[np]);
            qa2R[n] += r22; qa2I[n] += i22;
            const [r11, i11] = g(Tfull[0], b[np]);
            qb2R[n] += r11; qb2I[n] += i11;
            continue;
          }
          const t11r = Tfull[0].re[o], t11i = Tfull[0].im[o];
          const t12r = Tfull[1].re[o], t12i = Tfull[1].im[o];
          const t21r = Tfull[2].re[o], t21i = Tfull[2].im[o];
          const t22r = Tfull[3].re[o], t22i = Tfull[3].im[o];
          const M = (tr, ti) => [cr * tr - ci * ti, cr * ti + ci * tr];
          const [m11r, m11i] = M(t11r, t11i), [m12r, m12i] = M(t12r, t12i);
          const [m21r, m21i] = M(t21r, t21i), [m22r, m22i] = M(t22r, t22i);
          const an_ = a[np], bn_ = b[np];
          qa1R[n] += m11r * an_ + m12r * bn_; qa1I[n] += m11i * an_ + m12i * bn_;
          qa2R[n] += m21r * an_ + m22r * bn_; qa2I[n] += m21i * an_ + m22i * bn_;
          qb1R[n] += m11r * bn_ + m12r * an_; qb1I[n] += m11i * bn_ + m12i * an_;
          qb2R[n] += m21r * bn_ + m22r * an_; qb2I[n] += m21i * bn_ + m22i * an_;
        }
      }

      for (let d = 0; d < nd; d++) {
        if (m === 0) {
          let sr = 0, si = 0, tr = 0, ti = 0;
          for (let n = 1; n <= nmax; n++) {
            const v = DV.dv2[d * S + n];
            sr += v * qa2R[n]; si += v * qa2I[n];
            tr += v * qb2R[n]; ti += v * qb2I[n];
          }
          vvR[d] += sr; vvI[d] += si; hhR[d] += tr; hhI[d] += ti;
          continue;
        }
        const fc = 2 * Math.cos(m * dphi[d]), fs = 2 * Math.sin(m * dphi[d]);
        let ua1r = 0, ua1i = 0, va2r = 0, va2i = 0, ub1r = 0, ub1i = 0, vb2r = 0, vb2i = 0;
        let va1r = 0, va1i = 0, ua2r = 0, ua2i = 0, vb1r = 0, vb1i = 0, ub2r = 0, ub2i = 0;
        for (let n = 1; n <= nmax; n++) {
          const u = m * DV.dv1[d * S + n], v = DV.dv2[d * S + n];
          ua1r += u * qa1R[n]; ua1i += u * qa1I[n];
          va2r += v * qa2R[n]; va2i += v * qa2I[n];
          ub1r += u * qb1R[n]; ub1i += u * qb1I[n];
          vb2r += v * qb2R[n]; vb2i += v * qb2I[n];
          va1r += v * qa1R[n]; va1i += v * qa1I[n];
          ua2r += u * qa2R[n]; ua2i += u * qa2I[n];
          vb1r += v * qb1R[n]; vb1i += v * qb1I[n];
          ub2r += u * qb2R[n]; ub2i += u * qb2I[n];
        }
        vvR[d] += fc * (ua1r + va2r); vvI[d] += fc * (ua1i + va2i);
        vhR[d] += fs * (ub1r + vb2r); vhI[d] += fs * (ub1i + vb2i);
        hvR[d] -= fs * (va1r + ua2r); hvI[d] -= fs * (va1i + ua2i);
        hhR[d] += fc * (vb1r + ub2r); hhI[d] += fc * (vb1i + ub2i);
      }
    }
    for (let d = 0; d < nd; d++) {
      vvR[d] /= k; vvI[d] /= k; vhR[d] /= k; vhI[d] /= k;
      hvR[d] /= k; hvI[d] /= k; hhR[d] /= k; hhI[d] /= k;
    }
    return { vvR, vvI, vhR, vhI, hvR, hvI, hhR, hhI };
  }

  /* orientation-averaged phase function, Csca and g */
  function phaseFunctionRandom(blocks, nmax, k, nBeta, nPsi, nTheta) {
    nBeta = nBeta || 10; nPsi = nPsi || 24; nTheta = nTheta || (nmax + 20);
    const Tfull = fullT(blocks, nmax);
    const gb = gaussLegendre(nBeta), gm = gaussLegendre(nTheta);
    const nd = nTheta * nPsi;
    const ct = new Float64Array(nd), dphi = new Float64Array(nd);
    const Z11 = new Float64Array(nTheta);

    for (let b = 0; b < nBeta; b++) {
      const ct0 = gb.x[b], st0 = Math.sqrt(Math.max(1 - ct0 * ct0, 0));
      for (let t = 0; t < nTheta; t++) {
        const CT = gm.x[t], ST = Math.sqrt(Math.max(1 - CT * CT, 0));
        for (let p = 0; p < nPsi; p++) {
          const ps = 2 * Math.PI * p / nPsi, cp = Math.cos(ps), sp = Math.sin(ps);
          const nz = ct0 * CT - st0 * ST * cp;
          const nx = st0 * CT + ct0 * ST * cp;
          const ny = ST * sp;
          ct[t * nPsi + p] = Math.min(1, Math.max(-1, nz));
          dphi[t * nPsi + p] = Math.atan2(ny, nx);
        }
      }
      const S = amplitudesVec(Tfull, nmax, k, ct0, ct, dphi);
      for (let t = 0; t < nTheta; t++) {
        let acc = 0;
        for (let p = 0; p < nPsi; p++) {
          const d = t * nPsi + p;
          acc += 0.5 * (S.vvR[d] ** 2 + S.vvI[d] ** 2 + S.vhR[d] ** 2 + S.vhI[d] ** 2
                      + S.hvR[d] ** 2 + S.hvI[d] ** 2 + S.hhR[d] ** 2 + S.hhI[d] ** 2);
        }
        Z11[t] += 0.5 * gb.w[b] * acc / nPsi;
      }
    }
    let den = 0, num = 0;
    for (let t = 0; t < nTheta; t++) { den += gm.w[t] * Z11[t]; num += gm.w[t] * Z11[t] * gm.x[t]; }
    return { mu: gm.x, Z11, csca: 2 * Math.PI * den, g: num / den };
  }

  /* Pick nmax by minimising |albedo - 1| for a lossless particle. See tmatrix.py. */
  function bestNmaxLossless(rev, k, mr, shape, eps, chebN, capNmax) {
    const n0 = nmaxDefault(k * rev);
    let best = null;
    const hi = Math.min(n0 + 10, capNmax || 40);
    for (let nmax = Math.max(4, n0 - 4); nmax <= hi; nmax++) {
      let r;
      try { r = tmatrix(rev, k, mr, 0, shape, eps, nmax, nmax * 2, chebN); }
      catch (e) { break; }
      const err = Math.abs(crossSectionsRandom(r.blocks, k, rev).albedo - 1);
      if (!best || err < best.err) best = { blocks: r.blocks, nmax, err };
      if (best && err > 100 * best.err && err > 1e-3) break;
    }
    if (!best) throw new Error('no usable nmax');
    return best;
  }

  /* ---------------- self-test against the Python reference ---------------- */

  function selfTest(ref) {
    const TOL = 1e-8;
    const out = [];
    let worst = 0;
    const bump = (e, msg) => {
      if (!isFinite(e)) { worst = Infinity; out.push(msg + ' [non-finite]'); return; }
      worst = Math.max(worst, e);
      if (e > TOL) out.push(msg + ` err=${e.toExponential(2)}`);
    };
    for (const c of ref.tmatrix) {
      const r = tmatrix(c.rev, c.k, c.mr, c.mi, c.shape, c.eps, c.nmax, c.ngauss, c.chebN);
      const cs = crossSectionsRandom(r.blocks, c.k, c.rev);
      bump(Math.abs(cs.qext - c.qext) / Math.abs(c.qext), `${c.name} qext:`);
      bump(Math.abs(cs.qsca - c.qsca) / Math.abs(c.qsca), `${c.name} qsca:`);
      const pf = phaseFunctionRandom(r.blocks, c.nmax, c.k, c.nBeta, c.nPsi, c.nTheta);
      bump(Math.abs(pf.g - c.g) / Math.abs(c.g), `${c.name} g:`);
      bump(Math.abs(pf.csca - c.csca_quad) / Math.abs(c.csca_quad), `${c.name} csca_quad:`);

      const Tf = fullT(r.blocks, c.nmax);
      const S = amplitudesVec(Tf, c.nmax, c.k, c.ct0, Float64Array.from(c.ct), Float64Array.from(c.dphi));
      // all four amplitude-matrix elements, judged on the scale of the largest one
      // (the cross-polarised terms vanish at dphi = 0, so elementwise relative error
      // would be meaningless there)
      const comps = [ ['vv', c.absS], ['vh', c.absSvh], ['hv', c.absShv], ['hh', c.absShh]]
        .filter(([, ref]) => Array.isArray(ref));
      let sm = 0;
      for (const [, ref] of comps) for (let i = 0; i < ref.length; i++) sm = Math.max(sm, ref[i]);
      for (const [nm, ref] of comps) {
        const re = S[nm + 'R'], im = S[nm + 'I'];
        for (let i = 0; i < c.ct.length; i++) {
          bump(Math.abs(Math.hypot(re[i], im[i]) - ref[i]) / sm, `${c.name} |S_${nm}|[${i}]:`);
        }
      }
    }
    return { pass: worst <= TOL, worst, failures: out };
  }

  return { SPHEROID, CYLINDER, CHEBYSHEV, BICONCAVE, gaussLegendre, gaussNodes, profile, vig, vigampl,
           tmatrix, crossSectionsRandom, fullT, amplitudesVec, phaseFunctionRandom,
           bestNmaxLossless, nmaxDefault, selfTest };
})();
